# Build overview.md from the verified quotations (work/quotes.tsv) and the citation metadata (work/cite_meta.tsv).
import sys, json, csv
sys.path.insert(0, "/Users/jbotts/frus-analysis/c3/runs/r1/scripts")
import content as K
C = K.Citer()
c = C.c
used_quotes = []
def bq(qid, lead):
    q = K.QUOTES[qid]
    used_quotes.append(qid)
    C.c(q["key"])  # records the use
    return "%s\n\n> “%s”\n>\n> — %s\n" % (lead, q["text"], K.full_cite(q["key"]))

# reading accounting, taken from the ledger the reader script wrote
led = list(csv.DictReader(open(K.RUN + "/work/reading_ledger.tsv"), delimiter="\t"))
docs = {}
for r in led:
    k = (r["volume_id"], r["document_id"])
    d = docs.setdefault(k, {"whole": True, "pw": False})
